t-of-bounds could both apply prefer observable sink type; list at most one CWE unless multiple clearly distinct sink types (different branches) visible. For control-flow: verify validation before dangerous operation, verify break/return/continue terminates dangerous path, verify loop bounds against array sizes with quoted snippet pairs, verify integer arithmetic uses correct operators and checks underflow/overflow/unsigned wrap — state explicitly when guard checks one variable (authkey flags) but sink uses another (rka derived from payload.data[0]). For localization: snippet must contain sink line(s); include exact dereference lines; use ≤3 line ranges unless source and sink span more. Analysis priorities in sequence: (1) follow actual data-flow from input sources (arguments, parsed fields, external/network/file input) to sinks; quote snippet at each transition and state attacker-controlled; (2) check integer arithmetic for indexing (off-by-one > vs >=, overflow, underflow, unsigned wrap) against array bounds; (3) check missing/misplaced null/validity checks BEFORE dereference of pointers derived from untrusted input, verify guard applies to same pointer/field at sink; (4) check authorization/authentication order relative to dangerous actions (guard must precede sink and apply to sink's object); (5) check format-string, command-injection, HTML-output injection where user data reaches sink directly; (6) check missing/null payload/array/data validation before indexing — if payload.data, array base, or derived pointer indexed without prior null/non-empty validation treat as unvalidated access. Key failure-pattern checks to apply within each SCoT step: when pointer assigned from structured field (authkey->payload.data[0], ptr = obj->field) verify whether array/field itself validated before indexing — if not, assignment is unvalidated even if parent pointer (authkey) checked; when guard only checks parent object but sink dereferences derived pointer, state mismatch explicitly (derived pointer receives no guard); when dimensions/size validated before loop/decode confirm guard applies to all paths reaching sink inside loop. Verification rules: base reasoning only on given code; follow actual control flow (paths, checks, state changes) — confirm guard applies to attacker-controlled path and guards same object at sink; focus on security-relevant behavior (memory safety, bounds, lifetime, input validation, integer safety, authz/authn, unsafe APIs, unvalidated indexing); do NOT rewrite or modify code; do NOT claim vulnerability from snippet showing only validation without sink — only claim when both source and sink visible and unguarded (or guard misplaced/applying to wrong object); if ambiguous (full-function range, missing snippet, guard different variable than sink) prefer conservative verdict with lower confidence and state ambiguity in notes; set confidence proportional to evidence specificity (narrow line range + snippet at both source and sink + correct guard-check = higher; inference only/full range = lower; guard-check mismatch still supports vulnerability with moderate-high confidence because sink unguarded). Evidence anchoring: before any vulnerability conclusion quote snippet at dangerous operation (≤3 lines) and at input-to-sink transition separately; for derived pointers include both assignment and sink; for loop access quote index derivation and array access together; state whether guard applies to attacker-controlled path; state mismatch explicitly. Scan for systematic errors: high recall (0.95) with very low precision (0.51) indicates over-labeling — require both source and sink visible with specific line ranges; low localization precision (~28-31%) and low CWE accuracy (~20-31%) indicate weak anchoring — strengthen snippet requirements and CWE selection from observable sink; pairwise accuracy improving then dropping (6→11→16→13) shows instability — emphasize verification rules and conservative verdicts when evidence ambiguous. Do not add bias-correction framing ("lean toward not vulnerable", "when in doubt say not vulnerable"). Do not add few-shot examples. Do not change JSON output schema fields or types. The output format: first write SCoT reasoning in plain text with numbered steps using Sequence/Branch/Loop labels and anchoring each claim to snippet lines (start_line/end_line) with quoted snippets (≤3 lines around dangerous operation); then output ONLY one JSON object with no markdown, no extra text. Required JSON: {"verdict":{"vulnerable":bool,"confidence":float,"cwe":["CWE-..."],"severity":"low|medium|high|critical|unknown","summary":"..."},"evidence":[{"file":null,"function":null,"location":{"start_line":null,"end_line":null},"snippet":"...","reason":"..."}],"notes":{"assumptions":[],"limitations":[]}} Code: cookedprint(
	int datatype,
	int length,
	const char *data,
	int status,
	int quiet,
	FILE *fp
	)
{
	char *name;
	char *value;
	char output_raw;
	int fmt;
	l_fp lfp;
	sockaddr_u hval;
	u_long uval;
	int narr;
	size_t len;
	l_fp lfparr[8];
	char b[12];
	char bn[2 * MAXVARLEN];
	char bv[2 * MAXVALLEN];

	UNUSED_ARG(datatype);

	if (!quiet)
		fprintf(fp, "status=%04x %s,\n", status,
			statustoa(datatype, status));

	startoutput();
	while (nextvar(&length, &data, &name, &value)) {
		fmt = varfmt(name);
		output_raw = 0;
		switch (fmt) {

		case PADDING:
			output_raw = '*';
			break;

		case TS:
			if (!decodets(value, &lfp))
				output_raw = '?';
			else
				output(fp, name, prettydate(&lfp));
			break;

		case HA:	/* fallthru */
		case NA:
			if (!decodenetnum(value, &hval)) {
				output_raw = '?';
			} else if (fmt == HA){
				output(fp, name, nntohost(&hval));
			} else {
				output(fp, name, stoa(&hval));
			}
			break;

		case RF:
			if (decodenetnum(value, &hval)) {
				if (ISREFCLOCKADR(&hval))
					output(fp, name,
					       refnumtoa(&hval));
				else
					output(fp, name, stoa(&hval));
			} else if (strlen(value) <= 4) {
				output(fp, name, value);
			} else {
				output_raw = '?';
			}
			break;

		case LP:
			if (!decodeuint(value, &uval) || uval > 3) {
				output_raw = '?';
			} else {
				b[0] = (0x2 & uval)
					   ? '1'
					   : '0';
				b[1] = (0x1 & uval)
					   ? '1'
					   : '0';
				b[2] = '\0';
				output(fp, name, b);
			}
			break;

		case OC:
			if (!decodeuint(value, &uval)) {
				output_raw = '?';
			} else {
				snprintf(b, sizeof(b), "%03lo", uval);
				output(fp, name, b);
			}
			break;

		case AR:
			if (!decodearr(value, &narr, lfparr))
				output_raw = '?';
			else
				outputarr(fp, name, narr, lfparr);
			break;

		case FX:
			if (!decodeuint(value, &uval))
				output_raw = '?';
			else
				output(fp, name, tstflags(uval));
			break;

		default:
			fprintf(stderr, "Internal error in cookedprint, %s=%s, fmt %d\n",
				name, value, fmt);
			output_raw = '?';
			break;
		}

		if (output_raw != 0) {
			/* TALOS-CAN-0063: avoid buffer overrun */
			atoascii(name, MAXVARLEN, bn, sizeof(bn));
			if (output_raw != '*') {
				atoascii(value, MAXVALLEN,
					 bv, sizeof(bv) - 1);
				len = strlen(bv);
				bv[len] = output_raw;
				bv[len+1] = '\0';
			} else {
				atoascii(value, MAXVALLEN,
					 bv, sizeof(bv));
			}
			output(fp, bn, bv);
		}
	}
	endoutput(fp);
